const tasks = $input.all().map(item => item.json);

return tasks.map(task => {
  const reminderMessage =
    `🚨 URGENT TASK ALERT: ${task.subject} — ${task.task} ` +
    `is due on ${task.deadline} (${task.days_remaining} days remaining). ` +
    `Priority: ${task.priority}.`;

  return {
    json: {
      ...task,
      reminderMessage
    }
  };
});

